        MatchGroup: {
            match_id: string;
            bank_line_id: string;
            settlement_id: string | null;
            psp_txn_ids: string[];
            order_ids: string[];
            gross: components["schemas"]["Money"];
            fees: components["schemas"]["Money"];
            tax: components["schemas"]["Money"];
            refunds: components["schemas"]["Money"];
            holds: components["schemas"]["Money"];
            /** @description Must equal the bank line credit. */
            net: components["schemas"]["Money"];
            /** @enum {string} */
            tier: "T0" | "T1" | "T2" | "T3" | "LLM";
            confidence: number;
            /** @description Human-readable, one line per rule fired. */
            evidence: string[];
        };
